import React, { useCallback, useMemo, useState } from 'react';
import axios from 'axios';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Divider,
  Grid,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { formatPeso } from '../utils/currency';

const API_URL = process.env.REACT_APP_API_URL || `${window.location.protocol}//${window.location.hostname || 'localhost'}:5001/api`;

function getErrorMessage(error, fallback) {
  const direct = error?.response?.data?.error;
  if (typeof direct === 'string' && direct.trim()) {
    return direct;
  }

  const nested = error?.response?.data?.error?.message;
  if (typeof nested === 'string' && nested.trim()) {
    return nested;
  }

  const message = error?.message;
  if (typeof message === 'string' && message.trim()) {
    return message;
  }

  return fallback;
}

function formatDateTime(value) {
  if (!value) return '-';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return '-';
  return parsed.toLocaleString();
}

function AdminGcashApprovals({ adminPassword }) {
  const authHeaders = useMemo(() => ({ headers: { 'x-admin-password': adminPassword } }), [adminPassword]);

  const [queueRows, setQueueRows] = useState([]);
  const [summary, setSummary] = useState({
    cash_approved: 0,
    gcash_approved: 0,
    gcash_pending: 0,
    gcash_rejected: 0,
  });
  const [approvalNotes, setApprovalNotes] = useState({});
  const [loading, setLoading] = useState(false);
  const [refreshVersion, setRefreshVersion] = useState(0);
  const [actionById, setActionById] = useState({});
  const [errorMessage, setErrorMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  const [selectedStatus, setSelectedStatus] = useState('pending');

  const filteredRows = useMemo(() => {
    if (!selectedStatus || selectedStatus === 'all') {
      return queueRows;
    }

    return queueRows.filter((row) => {
      const rowStatus = String(row.payment_status || row.status || 'pending').toLowerCase();
      return rowStatus === selectedStatus;
    });
  }, [queueRows, selectedStatus]);

  const loadData = useCallback(async () => {
    if (!adminPassword) {
      setQueueRows([]);
      setSummary({
        cash_approved: 0,
        gcash_approved: 0,
        gcash_pending: 0,
        gcash_rejected: 0,
      });
      return;
    }

    setLoading(true);
    setErrorMessage('');

    try {
      const [
        posPendingResult,
        posApprovedResult,
        posRejectedResult,
        posSummaryResult,
        rentalPendingResult,
        rentalApprovedResult,
        rentalRejectedResult,
        rentalSummaryResult,
        printPendingResult,
        printApprovedResult,
        printRejectedResult,
        printSummaryResult,
        opexSummaryResult,
      ] = await Promise.allSettled([
        axios.get(`${API_URL}/pos-sales/pending-payments`, authHeaders),
        axios.get(`${API_URL}/pos-sales/approved-payments`, authHeaders),
        axios.get(`${API_URL}/pos-sales/rejected-payments`, authHeaders),
        axios.get(`${API_URL}/pos-sales/payment-summary`, authHeaders),
        axios.get(`${API_URL}/units/payment-requests/pending`, authHeaders),
        axios.get(`${API_URL}/units/payment-requests/approved`, authHeaders),
        axios.get(`${API_URL}/units/payment-requests/rejected`, authHeaders),
        axios.get(`${API_URL}/units/payment-summary`, authHeaders),
        axios.get(`${API_URL}/transactions/print-service/pending-payments`, authHeaders),
        axios.get(`${API_URL}/transactions/print-service/approved-payments`, authHeaders),
        axios.get(`${API_URL}/transactions/print-service/rejected-payments`, authHeaders),
        axios.get(`${API_URL}/transactions/print-service/payment-summary`, authHeaders),
        axios.get(`${API_URL}/opex/summary`, authHeaders),
      ]);

      const posPendingResponse = posPendingResult.status === 'fulfilled' ? posPendingResult.value : null;
      const posApprovedResponse = posApprovedResult.status === 'fulfilled' ? posApprovedResult.value : null;
      const posRejectedResponse = posRejectedResult.status === 'fulfilled' ? posRejectedResult.value : null;
      const posSummaryResponse = posSummaryResult.status === 'fulfilled' ? posSummaryResult.value : null;
      const rentalPendingResponse = rentalPendingResult.status === 'fulfilled' ? rentalPendingResult.value : null;
      const rentalApprovedResponse = rentalApprovedResult.status === 'fulfilled' ? rentalApprovedResult.value : null;
      const rentalRejectedResponse = rentalRejectedResult.status === 'fulfilled' ? rentalRejectedResult.value : null;
      const rentalSummaryResponse = rentalSummaryResult.status === 'fulfilled' ? rentalSummaryResult.value : null;
      const printPendingResponse = printPendingResult.status === 'fulfilled' ? printPendingResult.value : null;
      const printApprovedResponse = printApprovedResult.status === 'fulfilled' ? printApprovedResult.value : null;
      const printRejectedResponse = printRejectedResult.status === 'fulfilled' ? printRejectedResult.value : null;
      const printSummaryResponse = printSummaryResult.status === 'fulfilled' ? printSummaryResult.value : null;
      const opexSummaryResponse = opexSummaryResult.status === 'fulfilled' ? opexSummaryResult.value : null;

      const posRows = [...
        (Array.isArray(posPendingResponse?.data?.data) ? posPendingResponse.data.data : []),
        (Array.isArray(posApprovedResponse?.data?.data) ? posApprovedResponse.data.data : []),
        (Array.isArray(posRejectedResponse?.data?.data) ? posRejectedResponse.data.data : []),
      ].map((row) => ({
        ...row,
        source_type: 'store',
        row_key: `store-${row.id}`,
      }));
      const rentalRows = [...
        (Array.isArray(rentalPendingResponse?.data?.data) ? rentalPendingResponse.data.data : []),
        (Array.isArray(rentalApprovedResponse?.data?.data) ? rentalApprovedResponse.data.data : []),
        (Array.isArray(rentalRejectedResponse?.data?.data) ? rentalRejectedResponse.data.data : []),
      ].map((row) => ({
        ...row,
        sold_by: row.created_by || '-',
        sold_at: row.created_at,
        subtotal: Number(row.amount || 0),
        source_type: 'pc_rental',
        row_key: `rental-${row.id}`,
        payment_status: row.payment_status || row.status || 'pending',
      }));
      const printRows = [...
        (Array.isArray(printPendingResponse?.data?.data) ? printPendingResponse.data.data : []),
        (Array.isArray(printApprovedResponse?.data?.data) ? printApprovedResponse.data.data : []),
        (Array.isArray(printRejectedResponse?.data?.data) ? printRejectedResponse.data.data : []),
      ].map((row) => ({
        ...row,
        unit_name: row.notes || 'Print Service',
        sold_by: row.sold_by || 'Admin',
        sold_at: row.sold_at,
        subtotal: Number(row.subtotal || 0),
        source_type: 'print_service',
        row_key: `print-${row.id}`,
      }));

      setQueueRows([...posRows, ...rentalRows, ...printRows]);

      const posSummary = posSummaryResponse?.data?.data || {};
      const rentalSummary = rentalSummaryResponse?.data?.data || {};
      const printSummary = printSummaryResponse?.data?.data || {};
      const opexSummary = opexSummaryResponse?.data?.data || {};
      const combinedCashApproved = Number(posSummary.cash_approved || 0) + Number(rentalSummary.cash_approved || 0) + Number(printSummary.cash_approved || 0);
      const opexOperatingRevenue = Number(opexSummary.operating_revenue || 0);

      setSummary({
        cash_approved: Number.isFinite(opexOperatingRevenue) && opexOperatingRevenue >= 0 ? opexOperatingRevenue : combinedCashApproved,
        gcash_approved: Number(posSummary.gcash_approved || 0) + Number(rentalSummary.gcash_approved || 0) + Number(printSummary.gcash_approved || 0),
        gcash_pending: Number(posSummary.gcash_pending || 0) + Number(rentalSummary.gcash_pending || 0) + Number(printSummary.gcash_pending || 0),
        gcash_rejected: Number(posSummary.gcash_rejected || 0) + Number(rentalSummary.gcash_rejected || 0) + Number(printSummary.gcash_rejected || 0),
      });

      const failures = [
        posPendingResult,
        posApprovedResult,
        posRejectedResult,
        posSummaryResult,
        rentalPendingResult,
        rentalApprovedResult,
        rentalRejectedResult,
        rentalSummaryResult,
        printPendingResult,
        printApprovedResult,
        printRejectedResult,
        printSummaryResult,
        opexSummaryResult,
      ]
        .filter((result) => result.status === 'rejected')
        .map((result) => getErrorMessage(result.reason, 'Failed to load some approval data'));

      if (failures.length > 0) {
        setErrorMessage(`Partial data loaded. ${failures[0]}`);
      }
    } catch (error) {
      setErrorMessage(getErrorMessage(error, 'Failed to load GCash approvals data.'));
    } finally {
      setLoading(false);
    }
  }, [adminPassword, authHeaders]);

  React.useEffect(() => {
    loadData();
  }, [loadData, refreshVersion]);

  const runAction = async (row, type) => {
    const rowKey = row.row_key || `${row.source_type}-${row.id}`;
    const notes = String(approvalNotes[rowKey] || '').trim();
    const endpoint = type === 'approve' ? 'approve-gcash' : 'reject-gcash';
    const isPcRental = row.source_type === 'pc_rental';
    const isPrintService = row.source_type === 'print_service';
    const url = isPcRental
      ? `${API_URL}/units/payment-requests/${row.id}/${endpoint}`
      : isPrintService
        ? `${API_URL}/transactions/print-service/${row.id}/${endpoint}`
      : `${API_URL}/pos-sales/${row.id}/${endpoint}`;

    setActionById((prev) => ({ ...prev, [rowKey]: type }));
    setErrorMessage('');
    setSuccessMessage('');

    try {
      await axios.post(
        url,
        {
          approved_by: 'Admin',
          approval_notes: notes || null,
        },
        authHeaders
      );

      setSuccessMessage(type === 'approve'
        ? isPcRental
          ? 'PC rental GCash request approved and time added.'
          : isPrintService
            ? 'Print service GCash payment approved.'
          : 'GCash sale approved.'
        : isPcRental
          ? 'PC rental GCash request rejected.'
          : isPrintService
            ? 'Print service GCash payment rejected.'
          : 'GCash sale rejected and stock restored.');
      setApprovalNotes((prev) => ({ ...prev, [rowKey]: '' }));

      const nextStatus = type === 'approve' ? 'approved' : 'rejected';
      setQueueRows((prevRows) => {
        const filteredRows = prevRows.filter((entry) => {
          const entryKey = entry.row_key || `${entry.source_type}-${entry.id}`;
          return entryKey !== rowKey;
        });

        const updatedRow = {
          ...row,
          payment_status: nextStatus,
          status: nextStatus,
          sold_at: row.sold_at || new Date().toISOString(),
        };

        return [...filteredRows, updatedRow];
      });
    } catch (error) {
      setErrorMessage(getErrorMessage(error, 'Unable to process GCash action.'));
    } finally {
      setActionById((prev) => ({ ...prev, [rowKey]: null }));
    }
  };

  return (
    <Box sx={{ width: '100%' }}>
      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 2, gap: 2, flexWrap: 'wrap' }}>
        <Typography variant="h5">GCash Approvals</Typography>
        <Button variant="outlined" onClick={() => setRefreshVersion((prev) => prev + 1)} disabled={loading}>
          Refresh
        </Button>
      </Stack>

      {errorMessage ? <Alert severity="error" sx={{ mb: 2 }}>{errorMessage}</Alert> : null}
      {successMessage ? <Alert severity="success" sx={{ mb: 2 }}>{successMessage}</Alert> : null}

      <Grid container spacing={2} sx={{ mb: 2 }}>
        {[
          { label: 'Cash Approved', value: summary.cash_approved, status: 'cash' },
          { label: 'GCash Approved', value: summary.gcash_approved, status: 'approved' },
          { label: 'GCash Pending', value: summary.gcash_pending, status: 'pending' },
          { label: 'GCash Rejected', value: summary.gcash_rejected, status: 'rejected' },
        ].map((card) => {
          const isActive = selectedStatus === card.status;
          return (
            <Grid item xs={12} sm={6} md={3} key={card.label}>
              <Card
                variant={isActive ? 'elevation' : 'outlined'}
                onClick={() => card.status !== 'cash' && setSelectedStatus(card.status)}
                sx={{
                  cursor: card.status === 'cash' ? 'default' : 'pointer',
                  borderWidth: isActive ? 2 : 1,
                  borderColor: isActive ? 'primary.main' : 'divider',
                  transition: 'all 0.2s ease',
                  backgroundColor: isActive ? 'rgba(25, 118, 210, 0.04)' : 'inherit',
                }}
              >
                <CardContent>
                  <Typography variant="caption" color="text.secondary">{card.label}</Typography>
                  <Typography variant="h6">{formatPeso(card.value)}</Typography>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>

      <Card variant="outlined">
        <CardContent>
          <Typography variant="h6" sx={{ mb: 1 }}>
            {selectedStatus === 'pending' ? 'Pending Queue' : `${selectedStatus.charAt(0).toUpperCase()}${selectedStatus.slice(1)} Queue`}
          </Typography>
          <Divider sx={{ mb: 2 }} />

          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
              <CircularProgress size={28} />
            </Box>
          ) : filteredRows.length === 0 ? (
            <Alert severity="info">
              {selectedStatus === 'pending'
                ? 'No pending GCash payments.'
                : `No ${selectedStatus} GCash payments in the current queue.`}
            </Alert>
          ) : (
            <Box sx={{ overflowX: 'auto' }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Source</TableCell>
                    <TableCell>Reference</TableCell>
                    <TableCell>Unit</TableCell>
                    <TableCell>Sold By</TableCell>
                    <TableCell>GCash Ref</TableCell>
                    <TableCell>Amount</TableCell>
                    <TableCell>Created</TableCell>
                    <TableCell>Notes</TableCell>
                    <TableCell align="right">Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredRows.map((row) => {
                    const rowKey = row.row_key || `${row.source_type}-${row.id}`;
                    const actionState = actionById[rowKey];
                    const busy = actionState === 'approve' || actionState === 'reject';

                    return (
                      <TableRow key={rowKey} hover>
                        <TableCell>{row.source_type === 'pc_rental' ? 'PC Rental' : row.source_type === 'print_service' ? 'Print Service' : 'Store POS'}</TableCell>
                        <TableCell>{row.reference_no || '-'}</TableCell>
                        <TableCell>{row.unit_name || '-'}</TableCell>
                        <TableCell>{row.sold_by || '-'}</TableCell>
                        <TableCell>{row.payment_reference || '-'}</TableCell>
                        <TableCell>{formatPeso(Number(row.subtotal || 0))}</TableCell>
                        <TableCell>{formatDateTime(row.sold_at)}</TableCell>
                        <TableCell sx={{ minWidth: 220 }}>
                          <TextField
                            size="small"
                            fullWidth
                            placeholder="Approval notes (optional)"
                            value={approvalNotes[rowKey] || ''}
                            onChange={(event) => {
                              const nextValue = event.target.value;
                              setApprovalNotes((prev) => ({ ...prev, [rowKey]: nextValue }));
                            }}
                            disabled={busy || selectedStatus !== 'pending'}
                          />
                        </TableCell>
                        <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>
                          <Stack direction="row" spacing={1} justifyContent="flex-end">
                            <Button
                              variant="contained"
                              color="success"
                              size="small"
                              onClick={() => runAction(row, 'approve')}
                              disabled={busy || selectedStatus !== 'pending'}
                            >
                              {actionState === 'approve' ? 'Approving...' : 'Approve'}
                            </Button>
                            <Button
                              variant="contained"
                              color="error"
                              size="small"
                              onClick={() => runAction(row, 'reject')}
                              disabled={busy || selectedStatus !== 'pending'}
                            >
                              {actionState === 'reject' ? 'Rejecting...' : 'Reject'}
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </Box>
          )}
        </CardContent>
      </Card>
    </Box>
  );
}

export default AdminGcashApprovals;
